				managementFeePct: btrA.managementFeePct,
				commercialIncomeLines: commercialLinesFromBTR(btrA),
				carParkIncomeAnnual: btrA.carParkIncomeAnnual,
				buildingAdminFixed: btrA.buildingAdminFixed
